    ".cr-score-grade { min-width: 58px; border: 1px solid color-mix(in srgb, var(--cr-tone) 55%, var(--cr-line)); border-radius: 999px; padding: 5px 8px; color: var(--cr-tone) !important; text-align: center; font-weight: 850; }",
