el("reviewQueue")?.addEventListener("click", (event) => {
  if (state.sharedContextBusy) return;
  const descriptionToggle = event.target.closest("[data-context-room-proposal-description-toggle]");
  if (descriptionToggle) {
    const proposalId = descriptionToggle.dataset.contextRoomProposalDescriptionToggle;
    if (state.contextHubExpandedProposalDescriptions.has(proposalId)) state.contextHubExpandedProposalDescriptions.delete(proposalId);
    else state.contextHubExpandedProposalDescriptions.add(proposalId);
    renderContextRoomGlobalReviewQueue();
    window.requestAnimationFrame(() => document.querySelector('[data-context-room-proposal-description-toggle="' + CSS.escape(proposalId) + '"]')?.focus({ preventScroll: true }));
    return;
  }
  const selectionEntry = event.target.closest("[data-context-room-review-entry]");
  if (state.contextRoomSelectedReviews.size > 0 && selectionEntry) {
    const item = contextHubReviewItems().find((candidate) => candidate.id === selectionEntry.dataset.contextRoomReviewEntry);
    if (toggleContextRoomReviewSelection(item)) {
      event.preventDefault();
      event.stopPropagation();
      hideContextRoomReviewContextMenu();
      window.requestAnimationFrame(() => {
        document.querySelector('[data-context-room-review-entry="' + CSS.escape(item.id) + '"] button')?.focus({ preventScroll: true });
      });
      return;
    }
  }
  const modePrompt = event.target.closest("[data-context-room-mode-prompt]");
  if (modePrompt) {
    sendContextRoomModePrompt(modePrompt.dataset.contextRoomModePrompt).catch((error) => setStatus(error.message));
    return;
  }
  const button = event.target.closest("[data-context-room-review]");
  if (!button) return;
  const item = contextHubReviewItems().find((candidate) => candidate.id === button.dataset.contextRoomReview);
  if (!item) return;
  if (item.type === "local-proposal" || item.type === "local-asset") {
    import("/assets/local-proposal-review.mjs").then(({ openLocalProposalReview }) => openLocalProposalReview({ item, ...captureNotebookApi(item.projectId || ""), onChange: refreshContextRoomReviewQueue })).catch((error) => setStatus(error.message));
    return;
  }
  if (item.type === "shared") {
    if (state.sharedContextBusy) return;
    openSharedProposal(item.branch, item.repositoryId || item.repository).catch((error) => setStatus(error.message));
    return;
  }
  state.contextHubSelection = item.id;
  renderContextRoomGlobalReviewQueue();
  openContextHubProject(item.projectId, {
    reviewTarget: item.localReview || (item.localFile ? { path: item.localFile } : null),
  }).catch((error) => setStatus(error.message));
});
document.addEventListener("click", (event) => {
  if (!event.target.closest("[data-review-cleanup]")) return;
  import("/assets/review-cleanup.mjs").then(({ openReviewCleanup }) => openReviewCleanup({ api, onChange: refreshContextRoomReviewQueue })).catch((error) => setStatus(error.message));
});
document.addEventListener("click", (event) => {
  const button = event.target.closest("[data-local-draft]");
  if (!button) return;
  const item = (state.contextHub?.workingDrafts || []).find(draft => draft.id === button.dataset.localDraft && draft.projectId === button.dataset.draftProject);
  if (!item) return;
  import("/assets/local-draft-editor.mjs").then(({ openLocalDraftEditor }) => openLocalDraftEditor({ item,
    ...captureNotebookApi(item.projectId), onChange: refreshContextRoomReviewQueue })).catch(error => setStatus(error.message));
});
el("proposalReviewFiles")?.addEventListener("click", (event) => {
  if (event.target.closest("[data-proposal-review-more]")) {
    state.proposalReviewVisibleCount = Math.max(40, Number(state.proposalReviewVisibleCount || 40)) + 40;
    renderProposalReviewPage();
    return;
  }
  const unreview = event.target.closest("[data-proposal-unreview-path]");
  if (unreview && !unreview.disabled) {
    requestSharedProposalFileUnreview(unreview.dataset.proposalUnreviewPath);
    return;
  }
  const button = event.target.closest("[data-proposal-review-path]");
  if (!button || button.disabled) return;
  const filePath = button.dataset.proposalReviewPath;
  if (proposalReviewSuppressClickPath === filePath) {
    proposalReviewSuppressClickPath = "";
    event.preventDefault();
    return;
  }
  if (state.proposalSelectedFiles.size > 0 && toggleProposalReviewFileSelection(filePath)) {
    event.preventDefault();
    return;
  }
  if (state.contextRoomPreparingProposal) {
    const prepared = state.contextRoomPreparedReview;
    if (prepared?.url) {
      assignWorkspaceLocation(contextRoomProposalFileUrl(prepared.url, filePath));
      return;
    }
    state.contextRoomQueuedProposalFile = filePath;
    renderProposalReviewPage();
    setStatus("opening this file as soon as the exact review is ready...");
    return;
  }
  const reviewItem = state.docqa?.queue?.find((item) => item.path === filePath);
  const open = reviewItem
    ? openReviewQueueItem(reviewItem)
    : selectFile(filePath, { reviewMode: true });
  open.catch((error) => setStatus(error.message));
});
el("proposalReviewNotice")?.addEventListener("click", (event) => {
  if (event.target.closest("[data-proposal-open-retry]")) {
    retrySharedProposalOpening().catch((error) => setStatus(error.message));
    return;
  }
  if (event.target.closest("[data-proposal-open-refresh]")) {
    refreshSharedProposalOpening().catch((error) => setStatus(error.message));
    return;
  }
  if (event.target.closest("[data-proposal-open-back]")) returnFromProposalToHub();
});
function toggleProposalReviewFileSelection(filePath) {
  const entry = proposalReviewFileEntries().find((candidate) => candidate.path === filePath);
  if (!entry?.selectable) return false;
  state.proposalSelectionNotice = "";
  if (state.proposalSelectedFiles.has(filePath)) state.proposalSelectedFiles.delete(filePath);
  else state.proposalSelectedFiles.add(filePath);
  renderProposalReviewPage();
  return true;
}
function selectOrQueueProposalReviewFile(filePath) {
  filePath = normalizeUiPath(filePath);
  if (!filePath) return false;
  const entry = proposalReviewFileEntries().find((candidate) => candidate.path === filePath);
  if (!entry) return false;
  if (entry.reviewed) {
    state.proposalSelectionNotice = PROPOSAL_REVIEW_ALREADY_REVIEWED_NOTICE;
    renderProposalReviewPage();
    setStatus(PROPOSAL_REVIEW_ALREADY_REVIEWED_MESSAGE);
    return true;
  }
  if (state.contextRoomPreparingProposal) {
    const prepared = state.contextRoomPreparedReview;
    if (!prepared?.docqa) {
      setStatus("Review status is still loading. Try again when the row shows Review.");
      return true;
    }
    if (prepared?.url) {
      if (!entry.selectable) return false;
      assignWorkspaceLocation(contextRoomProposalSelectionUrl(prepared.url, filePath));
      return true;
    }
  }
  return toggleProposalReviewFileSelection(filePath);
}
function clearProposalReviewLongPress() {
  if (!proposalReviewLongPress) return;
  window.clearTimeout(proposalReviewLongPress.timer);
  proposalReviewLongPress = null;
}
el("proposalReviewFiles")?.addEventListener("contextmenu", (event) => {
  const button = event.target.closest("[data-proposal-review-path]");
  if (!button || !selectOrQueueProposalReviewFile(button.dataset.proposalReviewPath)) return;
  event.preventDefault();
});
el("proposalReviewFiles")?.addEventListener("pointerdown", (event) => {
  if (event.pointerType === "mouse" || event.button !== 0) return;
  const button = event.target.closest("[data-proposal-review-path]");
  const entry = button && proposalReviewFileEntries().find((candidate) => candidate.path === button.dataset.proposalReviewPath);
  if (!entry || (!entry.selectable && !entry.reviewed)) return;
  clearProposalReviewLongPress();
  proposalReviewLongPress = {
    pointerId: event.pointerId,
    path: entry.path,
    x: event.clientX,
    y: event.clientY,
    timer: window.setTimeout(() => {
      proposalReviewSuppressClickPath = entry.path;
      window.setTimeout(() => {
        if (proposalReviewSuppressClickPath === entry.path) proposalReviewSuppressClickPath = "";
      }, 900);
      selectOrQueueProposalReviewFile(entry.path);
      proposalReviewLongPress = null;
    }, PROPOSAL_REVIEW_LONG_PRESS_MS),
  };
});
el("proposalReviewFiles")?.addEventListener("pointermove", (event) => {
  if (!proposalReviewLongPress || proposalReviewLongPress.pointerId !== event.pointerId) return;
  if (Math.hypot(event.clientX - proposalReviewLongPress.x, event.clientY - proposalReviewLongPress.y) > 10) clearProposalReviewLongPress();
});
el("proposalReviewFiles")?.addEventListener("pointerup", clearProposalReviewLongPress);
el("proposalReviewFiles")?.addEventListener("pointercancel", clearProposalReviewLongPress);
el("proposalReviewSelection")?.addEventListener("click", (event) => {
  const selectAll = event.target.closest("[data-proposal-review-select-all]");
  if (selectAll) {
    const entries = proposalReviewFileEntries().filter((entry) => entry.selectable);
    if (selectAll.dataset.proposalReviewSelectAll === "clear") state.proposalSelectedFiles.clear();
    else for (const entry of entries) state.proposalSelectedFiles.add(entry.path);
    renderProposalReviewPage();
    return;
  }
  if (event.target.closest("[data-proposal-review-clear]")) {
    state.proposalSelectedFiles.clear();
    renderProposalReviewPage();
    return;
  }
  const batch = event.target.closest("[data-proposal-review-batch]");
  if (batch && !batch.disabled) requestSharedProposalFileBatch(batch.dataset.proposalReviewBatch);
});
